--

CREATE TABLE public.hr_attendance (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    company_id integer DEFAULT 1,
    employee_id uuid,
    date date NOT NULL,
    clock_in timestamp without time zone,
    clock_out timestamp without time zone,
    status character varying(50) DEFAULT 'Present'::character varying,
    location_in character varying(255),
    location_out character varying(255),
    overtime_hours numeric(5,2) DEFAULT 0,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    shift_id uuid,
    is_regularized boolean DEFAULT false,
    regularized_by uuid,
    regularized_at timestamp without time zone,
    work_from_home boolean DEFAULT false,
    geofence_status character varying(20),
    device_id character varying(100),
    early_departure boolean DEFAULT false,
    late_arrival boolean DEFAULT false,
    total_hours numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN ((clock_out IS NOT NULL) AND (clock_in IS NOT NULL)) THEN round((EXTRACT(epoch FROM (clock_out - clock_in)) / (3600)::numeric), 2)
    ELSE (0)::numeric
END) STORED
);


