    discount_amount numeric(15,2) DEFAULT 0,
    ai_risk_score integer,
    ai_risk_level character varying(20),
    ai_recommendation character varying(20),
    ai_insight text,
    fulfillment_status character varying(30) DEFAULT 'Unfulfilled'::character varying,
    sales_invoice_id uuid,
    updated_by uuid,
    total_shipped_value numeric(15,2) DEFAULT 0
);


ALTER TABLE public.orders OWNER TO erp_user;

--
-- Name: oms_distributor_perf; Type: MATERIALIZED VIEW; Schema: public; Owner: erp_user
--

CREATE MATERIALIZED VIEW public.oms_distributor_perf AS
 SELECT distributor_id,
    distributor_name,
    (count(*))::integer AS total_orders,
    COALESCE(sum(total_amount), (0)::numeric) AS total_value,
    COALESCE(avg(ai_risk_score), (0)::numeric) AS avg_risk_score,
    (count(*) FILTER (WHERE ((status)::text = ANY ((ARRAY['Delivered'::character varying, 'Invoiced'::character varying])::text[]))))::integer AS completed_count,
    (count(*) FILTER (WHERE ((status)::text = 'Cancelled'::text)))::integer AS cancelled_count
   FROM public.orders
  GROUP BY distributor_id, distributor_name
  ORDER BY COALESCE(sum(total_amount), (0)::numeric) DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.oms_distributor_perf OWNER TO erp_user;

--
-- Name: oms_monthly_trend; Type: MATERIALIZED VIEW; Schema: public; Owner: erp_user
--

CREATE MATERIALIZED VIEW public.oms_monthly_trend AS
 SELECT date_trunc('month'::text, (order_date)::timestamp with time zone) AS month,
    (count(*))::integer AS total_orders,
    COALESCE(sum(total_amount), (0)::numeric) AS total_amount,
    COALESCE(sum(total_amount) FILTER (WHERE ((status)::text = 'Invoiced'::text)), (0)::numeric) AS invoiced_amount,
    (count(*) FILTER (WHERE ((status)::text = 'Invoiced'::text)))::integer AS invoiced_count,
    COALESCE(sum(total_amount) FILTER (WHERE ((ai_risk_level)::text = 'High'::text)), (0)::numeric) AS high_risk_amount,
    (count(*) FILTER (WHERE ((ai_risk_level)::text = 'High'::text)))::integer AS high_risk_count
   FROM public.orders
  GROUP BY (date_trunc('month'::text, (order_date)::timestamp with time zone))
  ORDER BY (date_trunc('month'::text, (order_date)::timestamp with time zone)) DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.oms_monthly_trend OWNER TO erp_user;

