--
-- Name: oms_sla_breach; Type: VIEW; Schema: public; Owner: erp_user
--

CREATE VIEW public.oms_sla_breach AS
 SELECT id,
    order_number,
    distributor_id,
    distributor_name,
    status,
    priority,
    order_date,
    total_amount,
    (CURRENT_DATE - order_date) AS days_open,
    created_at
   FROM public.orders o
  WHERE (((status)::text <> ALL ((ARRAY['Delivered'::character varying, 'Invoiced'::character varying, 'Rejected'::character varying, 'Cancelled'::character varying])::text[])) AND ((CURRENT_DATE - order_date) > 7))
  ORDER BY (CURRENT_DATE - order_date) DESC;


