--
-- Name: vw_leave_balance; Type: VIEW; Schema: public; Owner: erp_user
--

CREATE VIEW public.vw_leave_balance AS
 SELECT id,
    company_id,
    employee_id,
    year,
    leave_type,
    allocated,
    used,
    carried_forward,
    pending_approval,
    encashed,
    lapsed,
    updated_at,
    GREATEST(((((allocated + carried_forward) - used) - pending_approval) - encashed), (0)::numeric) AS available_balance
   FROM public.hr_leave_balances lb;


ALTER VIEW public.vw_leave_balance OWNER TO erp_user;

--
-- Name: vw_profit_loss; Type: VIEW; Schema: public; Owner: erp_user
--

CREATE VIEW public.vw_profit_loss AS
 SELECT coa.account_type,
    coa.account_name,
    coa.company_id,
    COALESCE(sum((gl.debit - gl.credit)), (0)::numeric) AS amount
   FROM (public.chart_of_accounts coa
     JOIN public.general_ledger gl ON ((coa.id = gl.account_id)))
  WHERE ((coa.account_type)::text = ANY (ARRAY[('Income'::character varying)::text, ('Expense'::character varying)::text]))
  GROUP BY coa.account_type, coa.account_name, coa.company_id;


ALTER VIEW public.vw_profit_loss OWNER TO erp_user;

--
-- Name: vw_trial_balance; Type: VIEW; Schema: public; Owner: erp_user
--

CREATE VIEW public.vw_trial_balance AS
 SELECT coa.id AS account_id,
    coa.account_code,
    coa.account_name,
    coa.account_type,
    coa.company_id,
    COALESCE(sum(gl.debit), (0)::numeric) AS total_debit,
    COALESCE(sum(gl.credit), (0)::numeric) AS total_credit,
    COALESCE(sum((gl.debit - gl.credit)), (0)::numeric) AS net_balance
   FROM (public.chart_of_accounts coa
     LEFT JOIN public.general_ledger gl ON ((coa.id = gl.account_id)))
  GROUP BY coa.id, coa.account_code, coa.account_name, coa.account_type, coa.company_id;


ALTER VIEW public.vw_trial_balance OWNER TO erp_user;

